import { serverEnv } from "./server-env";
import type { PlanRoomPixels } from "./floor-layout";

const MODELS = ["gemini-2.5-flash", "gemini-2.0-flash", "gemini-flash-latest"];

const PROMPT = `Trace this Matterport colored floorplan. Return JSON only, with this shape:
{"rooms":[{"label":"Kitchen","points":[[x,y]]}]}
points are pixel coordinates. The origin is the top-left corner of the image, x increases to the right, and y increases downward.
Trace the floor outline of every labeled room. Include Main Dining Room, Kitchen, Freezer (the label may be cut off as Fre), Bar, Office, Bath, Front, Storage, Hallway, and any other named room you can see.
Follow the corners. Use between 6 and 24 points for each room. Do not include furniture, dimension text, or the building exterior as a room. Polygons must not cross themselves.`;

const roomsByModel = new Map<string, PlanRoomPixels[]>();

export async function traceFloorplan(modelId: string, bytes: Buffer, mimeType: string): Promise<PlanRoomPixels[]> {
  const cached = roomsByModel.get(modelId);
  if (cached) return cached;
  const key = serverEnv("GEMINI_API_KEY");
  if (!key) throw new Error("GEMINI_API_KEY is missing on the server.");

  let lastError = "Gemini did not return room polygons.";
  for (const model of MODELS) {
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
      {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-goog-api-key": key,
        },
        body: JSON.stringify({
          contents: [
            {
              parts: [
                { text: PROMPT },
                { inlineData: { mimeType, data: bytes.toString("base64") } },
              ],
            },
          ],
          generationConfig: { temperature: 0.1, responseMimeType: "application/json" },
        }),
        cache: "no-store",
      },
    );
    if (response.status === 404) {
      lastError = `${model} is not available.`;
      continue;
    }
    const body = (await response.json()) as {
      error?: { message?: string };
      candidates?: { content?: { parts?: { text?: string }[] } }[];
    };
    if (!response.ok) {
      lastError = body.error?.message || `Gemini request failed (${response.status}).`;
      if (response.status === 400 || response.status === 401 || response.status === 403) break;
      continue;
    }
    const text = body.candidates?.[0]?.content?.parts?.map((part) => part.text || "").join("\n") || "";
    const rooms = parseRooms(text);
    if (rooms.length === 0) {
      lastError = "Gemini did not name any rooms on this floorplan.";
      continue;
    }
    roomsByModel.set(modelId, rooms);
    return rooms;
  }
  throw new Error(lastError);
}

function parseRooms(text: string): PlanRoomPixels[] {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end <= start) return [];
  let parsed: unknown;
  try {
    parsed = JSON.parse(text.slice(start, end + 1));
  } catch {
    return [];
  }
  const source = parsed as { rooms?: unknown };
  const rooms = Array.isArray(source.rooms) ? source.rooms : Array.isArray(parsed) ? parsed : [];
  return rooms.flatMap((entry) => {
    if (!entry || typeof entry !== "object") return [];
    const record = entry as { label?: unknown; name?: unknown; points?: unknown };
    const label = String(record.label || record.name || "").trim();
    if (!label) return [];
    const pixels = asPixels(record.points);
    return pixels.length >= 3 ? [{ label, pixels }] : [];
  });
}

function asPixels(value: unknown): [number, number][] {
  if (!Array.isArray(value)) return [];
  const points: [number, number][] = [];
  for (const point of value) {
    if (Array.isArray(point) && point.length >= 2 && Number.isFinite(Number(point[0])) && Number.isFinite(Number(point[1]))) {
      points.push([Number(point[0]), Number(point[1])]);
      continue;
    }
    if (point && typeof point === "object") {
      const record = point as { x?: unknown; y?: unknown };
      if (Number.isFinite(Number(record.x)) && Number.isFinite(Number(record.y))) {
        points.push([Number(record.x), Number(record.y)]);
      }
    }
  }
  return points;
}
